def match(orders):
    trades = []
    buy_book = []  # (price, arrival_time, id, qty)
    sell_book = []  # (price, arrival_time, id, qty)
    order_map = {}  # id -> (side, price, qty, arrival_time) for tracking resting orders
    next_arrival = 0

    for order in orders:
        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, price, qty, arrival = order_map[order_id]
                del order_map[order_id]

                if side == 'buy':
                    buy_book[:] = [(p, a, oid, q) for p, a, oid, q in buy_book if oid != order_id]
                else:
                    sell_book[:] = [(p, a, oid, q) for p, a, oid, q in sell_book if oid != order_id]
            continue

        order_type = order[0]
        order_id = order[1]
        side = order[2]
        qty = order[4] if len(order) > 4 else order[3]
        price = order[3] if len(order) > 4 else None

        current_arrival = next_arrival
        next_arrival += 1

        if side == 'buy':
            # Match against sell book
            while qty > 0 and sell_book:
                sell_book.sort()
                best_sell = sell_book[0]
                sell_price, sell_arrival, sell_id, sell_qty = best_sell

                if price is None or sell_price <= price:
                    trade_qty = min(qty, sell_qty)
                    trades.append([order_id, sell_id, sell_price, trade_qty])
                    qty -= trade_qty

                    if trade_qty == sell_qty:
                        sell_book.pop(0)
                        if sell_id in order_map:
                            del order_map[sell_id]
                    else:
                        sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                        if sell_id in order_map:
                            order_map[sell_id] = (order_map[sell_id][0], order_map[sell_id][1], order_map[sell_id][2], sell_qty - trade_qty)
                else:
                    break

            # Rest remaining quantity if limit order
            if qty > 0 and order_type == 'limit':
                buy_book.append((price, current_arrival, order_id, qty))
                order_map[order_id] = ('buy', price, qty, current_arrival)

        else:  # side == 'sell'
            # Match against buy book
            while qty > 0 and buy_book:
                buy_book.sort(key=lambda x: (-x[0], x[1]))
                best_buy = buy_book[0]
                buy_price, buy_arrival, buy_id, buy_qty = best_buy

                if price is None or buy_price >= price:
                    trade_qty = min(qty, buy_qty)
                    trades.append([buy_id, order_id, buy_price, trade_qty])
                    qty -= trade_qty

                    if trade_qty == buy_qty:
                        buy_book.pop(0)
                        if buy_id in order_map:
                            del order_map[buy_id]
                    else:
                        buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)
                        if buy_id in order_map:
                            order_map[buy_id] = (order_map[buy_id][0], order_map[buy_id][1], order_map[buy_id][2], buy_qty - trade_qty)
                else:
                    break

            # Rest remaining quantity if limit order
            if qty > 0 and order_type == 'limit':
                sell_book.append((price, current_arrival, order_id, qty))
                order_map[order_id] = ('sell', price, qty, current_arrival)

    return trades

